class Engine:
    def __init__(self, capacity=0):
        self.capacity = capacity

    def printDetails(self):
        print("引擎规格:", self.capacity)


class Tires:
    def __init__(self, tires=0):
        self.tires = tires

    def printDetails(self):
        print("轮胎数:", self.tires)


class Doors:
    def __init__(self, doors=0):
        self.doors = doors

    def printDetails(self):
        print("车门数:", self.doors)


class Car:
    def __init__(self, eng, tr, dr, color):
        self.eObj = Engine(eng) # 创建发动机对象，并非引用
        self.tObj = Tires(tr)   # 创建轮胎对象，并非引用
        self.dObj = Doors(dr)   # 创建车门对象，并非引用
        self.color = color

    def printDetails(self):
        self.eObj.printDetails()
        self.tObj.printDetails()
        self.dObj.printDetails()
        print("汽车颜色", self.color)


car = Car(1600, 4, 2, "黑色")
car.printDetails()
